import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { Suspense } from "react";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { getCartItems } from "@/lib/cart";
import { priceCart } from "@/lib/pricing";
import { razorpayConfigured } from "@/lib/razorpay";
import { EMI_MIN_AMOUNT, SITE, whatsappLink } from "@/lib/site";
import { CheckoutForm } from "@/components/store/CheckoutForm";

export const metadata: Metadata = { title: "Checkout", robots: { index: false } };

async function CheckoutContent() {
  const user = await requireUser("/checkout");
  const items = (await getCartItems()).filter((i) => i.product.isActive && i.product.stock > 0);
  if (!items.length) redirect("/cart");
  const [quote, addresses] = await Promise.all([
    priceCart(items.map((i) => ({ productId: i.productId, quantity: i.quantity, engravingText: i.engravingText }))),
    db.address.findMany({ where: { userId: user.id }, orderBy: [{ isDefault: "desc" }, { createdAt: "desc" }] }),
  ]);

  return (
    <>
      {!razorpayConfigured() && (
        <div className="mb-4 rounded-md border border-warn/40 bg-warn/10 p-4 text-sm">
          Online payments are not configured yet (add Razorpay keys to <code>.env</code>). Meanwhile customers can{" "}
          <a className="font-semibold underline" href={whatsappLink("I'd like to place an order")}>order on WhatsApp</a> or call {SITE.phone}.
        </div>
      )}
      <CheckoutForm
        user={{ name: user.name, email: user.email, phone: user.phone }}
        addresses={addresses}
        lines={quote.lines.map((l, i) => ({ id: `${l.productId}-${i}`, name: l.name, image: l.image, quantity: l.quantity, price: l.unitPrice, engravingText: l.engravingText }))}
        totals={{ subtotal: quote.subtotal, discount: quote.discount, shippingFee: quote.shippingFee, taxTotal: quote.taxTotal, total: quote.total }}
        emiAvailable={quote.emiEligible && quote.total >= EMI_MIN_AMOUNT}
      />
    </>
  );
}

export default function CheckoutPage() {
  return (
    <div className="container-x py-6">
      <div className="mb-4 flex items-center justify-between">
        <h1 className="font-display text-3xl font-semibold">Checkout</h1>
        <Link href="/cart" className="text-sm text-maroon hover:underline">Back to cart</Link>
      </div>
      <Suspense fallback={<div className="h-96 skeleton rounded-xl" />}>
        <CheckoutContent />
      </Suspense>
    </div>
  );
}
